use std::{env,fs,path::PathBuf};
fn main(){let path="../../src/eva_companion.rs";println!("cargo:rerun-if-changed={path}");let source=fs::read_to_string(path).unwrap();let start=source.find("fn safe_edge(").unwrap();let body=start+source[start..].find('{').unwrap();let mut depth=1;let mut end=body+1;for (i,c)in source[body+1..].char_indices(){match c{'{'=>depth+=1,'}'=>depth-=1,_=>{}}if depth==0{end=body+2+i;break;}}let function=&source[start..end];let code=format!("use companion_protocol::Rect;\n{function}\npub fn admit(size:(i32,i32),exclusions:&[Rect],full:(i32,i32),compact:(i32,i32))->Option<(Rect,bool)>{{safe_edge(size,exclusions,full,compact)}}\n");fs::write(PathBuf::from(env::var_os("OUT_DIR").unwrap()).join("geometry.rs"),code).unwrap();}
